var isGood = function(nums) {
    if (nums.length === 2) {
        return nums[0] === nums[1] && nums[1] === 1;
    }

    return nums.reduce((acc, el) => acc ^ el, nums.length - 1) === 0;
};

/**
 * @param {number[]} nums
 * @return {boolean}
 */
var isGood = function(nums) {
    const n = nums.length - 1;
    const freq = Array(n + 1).fill(0);

    for (const num of nums) {
        if (num > n || (freq[num] > 0 && num !== n)) {
            return false;
        }

        freq[num]++;
    }

    return true;
};

