var isGood = function(nums) {
    const n = nums.length - 1;
    const freq = Array(n + 1).fill(0);

    for (const num of nums) {
        if (num < n && freq[num] !== 0) return false;
        if (num === n && freq[num] === 2) return false;
        if (num > n) return false;

        freq[num]++;
    }

